<section class="content"><div class="page-intro"><p>Review open blood requests and accept one you can help with.</p></div><div class="request-list"><?php $requests = $requests ?? []; $open = array_filter($requests, fn($r) => in_array($r['status'] ?? '', ['Pending','Donor matched'], true)); foreach ($open as $request): ?><div class="request-card"><div class="request-badge"><?= h($request['blood_group']) ?></div><div class="request-info"><div><span class="eyebrow"><?= h($request['id']) ?> · <?= h($request['created']) ?></span><h3><?= h($request['hospital']) ?></h3><p><?= h($request['recipient']) ?> needs <?= h((string) $request['units']) ?> unit(s) · <?= h($request['note'] ?: 'No additional details') ?></p></div><span class="urgency <?= strtolower($request['urgency']) ?>"><?= h($request['urgency']) ?></span></div><form method="post"><input type="hidden" name="action" value="accept_request"><input type="hidden" name="request_id" value="<?= h($request['id']) ?>"><button class="button primary" <?= ($request['status'] !== 'Pending' ? 'disabled' : '') ?>><?= $request['status'] === 'Pending' ? 'Accept request' : 'Matched' ?> <span>→</span></button></form></div><?php endforeach; ?></div></section>